/// <summary>
/// Maps the entity to the backing datasources.
/// </summary>
/// <param name = "entityCtx">The context of the entity.</param>
/// <param name = "dataSourceCtx">The context of the datasource being mapped.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    changecompany(this.Company)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTable))
        {
            LedgerJournalTable ledgerJournalTable = _dataSourceCtx.getBuffer();

            if (this.JournalBatchNumber)
            {
                ledgerJournalTable = LedgerJournalTable::find(this.JournalBatchNumber);
                this.LedgerJournalTableRecId = ledgerJournalTable.RecId;
            }

            _dataSourceCtx.setBuffer(ledgerJournalTable);
        }

        // When editing through the entity, always delay tax calculation to avoid
        // a O(n^2) tax calculation while importing multiple lines. The journal will
        // automatically calculate taxes later at posting time or when necessary.
        this.DelayTaxCalculation = NoYes::Yes;

        // Get the default dimensions if not specified in the input file.
        if (this.DefaultDimensionDisplayValue == '' || this.OffsetDefaultDimensionDisplayValue == '')
        {
            DimensionDefault defaultDimension, offsetDefaultDimension;

            switch (this.AccountType)
            {
                case LedgerJournalACType::Cust:
                    CustTable custTable = CustTable::findByCompany(this.PrimaryCompany,this.AccountDisplayValue,false);
                    if (custTable && this.DefaultDimensionDisplayValue == '')
                    {
                        defaultDimension = custTable.DefaultDimension;
                    }

                    if (this.OffsetDefaultDimensionDisplayValue == '')
                    {
                        CustTable custTableOffset = CustTable::findByCompany(this.OffsetCompany,this.OffsetAccountDisplayValue,false);
                        if (custTableOffset)
                        {
                            offsetDefaultDimension = custTableOffset.DefaultDimension;
                        }
                    }
                    break;

                case LedgerJournalACType::Vend:
                    VendTable vendTable = VendTable::findByCompany(this.PrimaryCompany,this.AccountDisplayValue,false);
                    if (vendTable && this.DefaultDimensionDisplayValue == '')
                    {
                        defaultDimension = vendTable.DefaultDimension;
                    }

                    if (this.OffsetDefaultDimensionDisplayValue == '')
                    {
                        VendTable vendTableOffset = VendTable::findByCompany(this.OffsetCompany,this.OffsetAccountDisplayValue,false);
                        if (vendTableOffset)
                        {
                            offsetDefaultDimension = vendTableOffset.DefaultDimension;
                        }
                    }
                    break;
            }

            // Assign only if values are retrieved
            if (this.DefaultDimensionDisplayValue == '')
            {
                this.DefaultDimension = defaultDimension;
            }

            if (this.OffsetDefaultDimensionDisplayValue == '')
            {
                this.OffsetDefaultDimension = offsetDefaultDimension;
            }
        }

        super(_entityCtx, _dataSourceCtx);
    }
}

/// <summary>
/// Validates the journal batch number to determine if the journal is valid.
/// </summary>
/// <returns>Returns true if the journal is valid; otherwise, false.</returns>
private boolean isJournalValid()
{
    return LedgerDailyJournalExcelTemplate::validateDailyJournal(this.JournalBatchNumber);
}

/// <summary>
/// Validates the write operation for the entity, ensuring the journal is valid and default dimension display values are set correctly.
/// </summary>
/// <returns>Returns true if the write operation is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    changecompany(this.Company)
    {
        boolean isValid = this.isJournalValid();

        if (isValid)
        {
            // skip setting default dimension display value if it is blank otherwise isFieldSet will set to true and further we can't set default dimension as it remains blank
            if (this.DefaultDimensionDisplayValue != '')
            {
                this.DefaultDimensionDisplayValue = METLedgerJournalGlobalEntityDMF::validateDefaultDimensionDisplayValueIsNonLedgerType(this.AccountType, this.DefaultDimensionDisplayValue);
            }

            if (this.OffsetDefaultDimensionDisplayValue != '')
            {
                this.OffsetDefaultDimensionDisplayValue = METLedgerJournalGlobalEntityDMF::validateDefaultDimensionDisplayValueIsNonLedgerType(this.OffsetAccountType, this.OffsetDefaultDimensionDisplayValue, true);
            }

            isValid = super();
        }

        return isValid;
    }
}

/// <summar
/// Warns if the default dimension is set when the account type is ledger.
/// </summary>
/// <param name = "_accountType">The account type.</param>
/// <param name = "_displayValue">The default dimension display value.</param>
/// <param name = "_isOffset">true if checking the offset field, otherwise, false.</param>
/// <returns>The resulting default dimension display value.</returns>
internal static DimensionDisplayValue validateDefaultDimensionDisplayValueIsNonLedgerType(LedgerJournalACType _accountType, DimensionDisplayValue _displayValue, boolean _isOffset = false)
{
    DimensionDisplayValue result = _displayValue;

    if (_accountType == LedgerJournalACType::Ledger && _displayValue != '')
    {
        FieldName displayValueFieldName = _isOffset ? fieldPName(METLedgerJournalGlobalEntityDMF, OffsetDefaultDimensionDisplayValue) : fieldPName(METLedgerJournalGlobalEntityDMF, DefaultDimensionDisplayValue);
        FieldName accountTypeFieldName = _isOffset ? fieldPName(METLedgerJournalGlobalEntityDMF, OffsetAccountType) : fieldPName(METLedgerJournalGlobalEntityDMF, AccountType);

        // Don't fail, only throw a warning.
        warning(strFmt("@GeneralLedger:JournalEntityDimensionsOnLedgerAccount",
            displayValueFieldName,
            accountTypeFieldName,
            enum2Str(LedgerJournalACType::Ledger)));

        result = '';
    }

    return result;
}

/// <summary>
/// Validates the delete operation for the entity, ensuring the journal is valid before proceeding.
/// </summary>
/// <returns>Returns true if the delete operation is valid; otherwise, false.</returns>
public boolean validateDelete()
{
    changecompany(this.Company)
    {
        boolean isValid = this.isJournalValid();

        if (isValid)
        {
            isValid = super();
        }

        return isValid;
    }
}

/// <summary>
/// Inserts the entity data source and performs additional processing specific to ledger journal transactions.
/// </summary>
/// <param name="_entityCtx">The runtime context of the data entity being inserted.</param>
/// <param name="_dataSourceCtx">The runtime context of the data source being inserted.</param>
/// <returns>Returns true if the insertion is successful; otherwise, false.</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    changecompany(this.Company)
    {
        //TODO: re-investigate for 10.0.41
        LedgerJournalTransTaxExtension ledgerJournalTransTaxExtension = METLedgerJournalGlobalEntityDMF::setLedgerJournalTransTaxExtension(_dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTrans))
        {
            METLedgerJournalGlobalEntityDMF entity = _entityCtx.getEntityRecord();
            LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

            this.resolveFinTags(entity, ledgerJournalTrans);
            ledgerJournalTrans.LineNum = ledgerJournalTrans.LineNum ? ledgerJournalTrans.LineNum : ledgerJournalTrans::lastLineNum(this.JournalBatchNumber) + 1;
            _dataSourceCtx.setBuffer(ledgerJournalTrans);
        }

        boolean ret = super(_entityCtx, _dataSourceCtx);

        if (ret && _dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTrans))
        {
            LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

            LedgerJournalEngine_Server::adjustDate(ledgerJournalTrans);

            LedgerJournalEngine::determineCashDiscountForEntities(ledgerJournalTrans);

            ttsbegin;
            ledgerJournalTrans.ExchRate             = ExchangeRateHelper::exchRate(ledgerJournalTrans.CurrencyCode, ledgerJournalTrans.TransDate);
            ledgerJournalTrans.setSettleVoucher();
            ledgerJournalTrans.doUpdate();
            ttscommit;
        }

        // When <c>LedgerJournalTransTaxExtension</c> is not inserted successfully and it links well with <c>LedgerJournalTrans</c>,
        // it should try to insert/update the table <c>LedgerJournalTransTaxExtension</c> with set value.
        if (!ret && ledgerJournalTransTaxExtension.LedgerJournalTrans)
        {
            ttsbegin;
            LedgerJournalTrans ledgerJournalTrans = ledgerJournalTransTaxExtension.getLedgerJournalTrans();
            ledgerJournalTransTaxExtension.save(ledgerJournalTrans, true);
            ttscommit;

            ret = true;
        }

        METLedgerJournalGlobalEntityDMF::saveDataSource(_dataSourceCtx);

        return ret;
    }
}

/// <summary>
/// Updates the entity data source and performs additional processing specific to ledger journal transactions.
/// </summary>
/// <param name="_entityCtx">The runtime context of the data entity being updated.</param>
/// <param name="_dataSourceCtx">The runtime context of the data source being updated.</param>
/// <returns>Returns true if the update is successful; otherwise, false.</returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    LedgerJournalTrans ledgerJournalTransOrig;

    changecompany(this.Company)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTrans))
        {
            ledgerJournalTransOrig = _dataSourceCtx.getBuffer().orig();

            METLedgerJournalGlobalEntityDMF entity = _entityCtx.getEntityRecord();
            LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

            this.resolveFinTags(entity, ledgerJournalTrans);
        }

        boolean ret = super(_entityCtx, _dataSourceCtx);

        if (ret && dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTrans) == _dataSourceCtx.name())
        {
            LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer();

            LedgerJournalEngine_Server::adjustDate(ledgerJournalTrans);

            LedgerJournalEngine::determineCashDiscountForEntities(ledgerJournalTrans, ledgerJournalTransOrig);
        }

        METLedgerJournalGlobalEntityDMF::saveDataSource(_dataSourceCtx);

        return ret;
    }
}

/// <summary>
/// Saves the data source and updates journal balances if necessary.
/// </summary>
/// <param name="_dataSourceCtx">The runtime context of the data source being saved.</param>
internal static void saveDataSource(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    METLedgerJournalGlobalEntityDMF lineEntity;
    if (_dataSourceCtx.name() == tableStr(LedgerJournalTrans) && lineEntity.checkShouldUpdateJournalHeaderBalance())
    {
        LedgerJournalTrans ledgerJournalTrans = _dataSourceCtx.getBuffer() as LedgerJournalTrans;

        // update the journal balances
        LedgerJournalTable ledgerJournalTable = LedgerJournalTable::find(ledgerJournalTrans.JournalNum);

        ledgerJournalTable.updateBalances();
    }
}

/// <summary>
/// Determines if the journal header balance should be updated during a journal line write event.
/// </summary>
/// <returns>true if the journal header balance should be updated, otherwise, false.</returns>
/// <remarks>
/// Provides a hook to override/opt out of the default behavior of updating the journal header balance with each line
/// write.  Once a platform deliverable is available allowing a hook for a post publish event to update the balance only
/// once, this will be a no-op.
///
/// If the customer opts out of the header balance updated - the journal balance will not be updated on the excel template,
/// but this does not impact the journal balance displayed on the form.
/// </remarks>
public boolean checkShouldUpdateJournalHeaderBalance()
{
    boolean shouldUpdateBalance = true;

    EventHandlerResult result = new EventHandlerResult();

    this.shouldUpdateJournalHeaderBalance(result);

    if (result.hasResult())
    {
        shouldUpdateBalance = result.result();
    }

    return shouldUpdateBalance;
}

/// <summary>
/// Raises an event providing a subsciber the option to opt out of the journal header balance
/// update with each journal line write.
/// </summary>
/// <param name = "_result">The <c>EventHandlerResult</c> instance.</param>
delegate void shouldUpdateJournalHeaderBalance(EventHandlerResult _result)
{
}

/// <summary>
/// Gets a custom account type lookup serialized string for the Account type field.
/// </summary>
/// <returns>A serialized string with a list of account types.</returns>
[
    SysODataActionAttribute('LedgerJournalGlobalEntityAccountTypeFieldCustomLookup', false),
    SysODataCollectionAttribute('_fields', Types::String),
    SysODataFieldLookupAttribute('AccountType')
]
public static str accountTypeCustomLookup(Array _fields)
{
    OfficeAppCustomLookupListResult result = new OfficeAppCustomLookupListResult();
    result.determinationFields().value(1, fieldStr(METLedgerJournalGlobalEntityDMF, AccountType));

    int current = 1;

    Set supportedTypes = new LedgerDailyJournalExcelTemplate().supportedAccountTypes();
    SetEnumerator supportedTypesEnumerator = supportedTypes.getEnumerator();

    while (supportedTypesEnumerator.moveNext())
    {
        LedgerJournalACType currentACType = supportedTypesEnumerator.current();
        result.items().value(current, enum2Str(currentACType));
        current++;
    }

    return result.serialize();
}

/// <summary>
