    SysODataFieldLookupAttribute('OffsetAccountType')
]
public static str offsetAccountTypeCustomLookup(Array _fields)
{
    OfficeAppCustomLookupListResult result = new OfficeAppCustomLookupListResult();
    result.determinationFields().value(1, fieldStr(METLedgerJournalGlobalEntityDMF, OffsetAccountType));

    int current = 1;

    Set supportedTypes = new LedgerDailyJournalExcelTemplate().supportedOffsetAccountTypes();
    SetEnumerator supportedTypesEnumerator = supportedTypes.getEnumerator();

    while (supportedTypesEnumerator.moveNext())
    {
        LedgerJournalACType currentACType = supportedTypesEnumerator.current();
        result.items().value(current, enum2Str(currentACType));
        current++;
    }

    return result.serialize();
}

private void resolveFinTags(METLedgerJournalGlobalEntityDMF _entity, LedgerJournalTrans _ledgerJournalTrans)
{
    //TODO: METCSAH team will re-investigate in v10.0.42 and decide whether to be removed or not
    //if (LedgerJournalBasedEntityFinTagResolverHelperFlight::instance().isEnabled())
    //{
    //    LedgerJournalBasedEntityFinTagResolverHelper::resolveFinTagsForLedgerJournalTrans(_entity.FinTagDisplayValue, _entity.OffsetFinTagDisplayValue, _ledgerJournalTrans);
    //}
    //else
    if(FinTagFeature::isEnabled())
    {
        _ledgerJournalTrans.FinTag = FinTagResolver::resolve(_entity.FinTagDisplayValue, _ledgerJournalTrans.Company);
        _ledgerJournalTrans.OffsetFinTag = FinTagResolver::resolve(_entity.OffsetFinTagDisplayValue, _ledgerJournalTrans.OffsetCompany);
    }
}

/// <summary>
/// Sets the value for table <c>LedgerJournalTransTaxExtension</c> when it is imported via journal line data entity.
/// </summary>
/// <param name = "_dataSourceCtx">The context of the datasource being mapped.</param>
/// <returns>The <c>LedgerJournalTransTaxExtension</c> record.</returns>
public static LedgerJournalTransTaxExtension setLedgerJournalTransTaxExtension(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    LedgerJournalTransTaxExtension ledgerJournalTransTaxExtension;
    boolean isExtensionEnabled;

    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(METLedgerJournalGlobalEntityDMF, LedgerJournalTransTaxExtension):
            isExtensionEnabled = Tax::isTaxIntegrationEnabledForBusinessProcess(TaxIntegrationBusinessProcess::Journal);
            break;

        case dataEntityDataSourceStr(ExpenseJournalLineEntity, LedgerJournalTransTaxExtension):
            isExtensionEnabled = Tax::isTaxIntegrationEnabledForBusinessProcess(TaxIntegrationBusinessProcess::Project);
            break;

        default:
            isExtensionEnabled = false;
            break;
    }

    if (isExtensionEnabled)
    {
        LedgerJournalTransTaxExtension ledgerJournalTransTaxExtBuffer = _dataSourceCtx.getBuffer();

        // When override sales tax is empty, it needs to get the value via default logic.
        ledgerJournalTransTaxExtBuffer.defaultRow();

        // Checks if extension table is inserted already since it may be inserted via LedgerJournalTrans.insert() method.
        // If yes, it should copy the data entity buffer to the extension table so that it can be updated later;
        // otherwise, it will set the data entity buffer to the empty extension table so that it can be inserted later.
        ledgerJournalTransTaxExtension =
            LedgerJournalTransTaxExtension::findByLedgerJournalTrans(ledgerJournalTransTaxExtBuffer.ledgerJournalTrans);
        buf2Buf(ledgerJournalTransTaxExtBuffer, ledgerJournalTransTaxExtension);
    }

    return ledgerJournalTransTaxExtension;
}

/// <summary>
/// Persists the entity data while skipping validation for specific fields.
/// </summary>
/// <param name="_entityCtx">The runtime context of the data entity being persisted.</param>
public void persistEntity(DataEntityRuntimeContext _entityCtx)
{
    this.skipDataSourceValidateField(fieldNum(METLedgerJournalGlobalEntityDMF, Voucher), true);
    this.skipDataSourceValidateField(fieldNum(METLedgerJournalGlobalEntityDMF, ExchRate), true);

    super(_entityCtx);
}

/// <summary>
/// Processes and stages data for a given DMF definition group execution.
/// </summary>
/// <param name="_dmfDefinitionGroupExecution">The DMF definition group execution object containing the execution details.</param>
public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    METLedgerJournalGlobalStagingDMF    globalStagingDMF,globalStagingDMFUpdate;
    LedgerJournalTable                  ledgerJournalTable;
    str                                 executionId;

    globalStagingDMF.clear();
    while select globalStagingDMF 
        group by JournalGroup,JournalName,Company
            where globalStagingDMF.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                && globalStagingDMF.ExecutionId    == _dmfDefinitionGroupExecution.ExecutionId
                && globalStagingDMF.JournalBatchNumber == ''
                && globalStagingDMF.JournalGroup != ''
    {
        changecompany (globalStagingDMF.Company)
        {
            ttsbegin;
            executionId = guid2Str(newGuid());
            ledgerJournalTable.clear();
            ledgerJournalTable.initValue();
            ledgerJournalTable.METJournalGroupExecutionId   = executionId;
            ledgerJournalTable.METJournalGroup              = globalStagingDMF.JournalGroup;
            ledgerJournalTable.JournalName                  = globalStagingDMF.JournalName;
            ledgerJournalTable.JournalNum                   = JournalTableData::newTable(ledgerJournalTable).nextJournalId();
            ledgerJournalTable.initFromLedgerJournalName();
            if (ledgerJournalTable.validateWrite())
            {
                ledgerJournalTable.insert();

                globalStagingDMFUpdate.clear();
                update_recordset globalStagingDMFUpdate
                    setting JournalBatchNumber = ledgerJournalTable.JournalNum
                    where globalStagingDMFUpdate.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                        && globalStagingDMFUpdate.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                        && globalStagingDMFUpdate.JournalGroup == globalStagingDMF.JournalGroup
                        && globalStagingDMFUpdate.Company == globalStagingDMF.Company
                        && globalStagingDMFUpdate.JournalBatchNumber == '';
            }

            // Generate the lineNumber so that during parallel import we will not have an issue
            METLedgerJournalGlobalEntityDMF::updateLineNumbers(_dmfDefinitionGroupExecution, ledgerJournalTable.JournalNum);

            ttscommit;
        }
    }
}

/// <summary>
/// Updates staging records with line number and line creation sequence number.
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">The definition group for which the line numbers should be updated.</param>
/// <param name = "_journalId">The Journal number should be updated.</param>
public static void updateLineNumbers(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution, LedgerJournalId _journalId)
{
    METLedgerJournalGlobalStagingDMF updateStaging;
    LedgerJournalTrans               ledgerJournalTrans;
    LineNum                          lineNum;

    lineNum = LedgerJournalTrans::lastLineNum(_journalId) + 1;

    while select forupdate updateStaging
        where updateStaging.DefinitionGroup     == _dmfDefinitionGroupExecution.DefinitionGroup
            && updateStaging.ExecutionId        == _dmfDefinitionGroupExecution.ExecutionId
            && updateStaging.JournalBatchNumber == _journalId
        notexists join ledgerJournalTrans
            where ledgerJournalTrans.JournalNum == updateStaging.JournalBatchNumber &&
            ledgerJournalTrans.LineNum          == updateStaging.LineNumber &&
            ledgerJournalTrans.DataAreaId       == updateStaging.Company
    {
        updateStaging.LineNumber = lineNum;
        updateStaging.update();

        lineNum ++;
    }
}
